import com.appwalied.quran.R;
import com.appwalied.quran.adabters.Adapterrec3;
import com.appwalied.quran.adabters.ItemModel;
import com.appwalied.quran.base.BaseActivity;
import com.appwalied.quran.databinding.ActivityMainhagandomraBinding;

import java.util.ArrayList;
import java.util.List;

public class Mainhagandomra extends BaseActivity {

    private ActivityMainhagandomraBinding binding;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        binding = ActivityMainhagandomraBinding.inflate(getLayoutInflater());
        setContentView(binding.getRoot());

        binding.backButton.setOnClickListener(v -> finish());

        binding.rec4.setLayoutManager(new LinearLayoutManager(this));

        List<ItemModel> list = new ArrayList<>();
        list.add(new ItemModel("الحج ركن من أركان الإسلام وفرض على كل مسلم مستطيع مرة واحدة في العمر، قال تعالى: (وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا) [آل عمران: 97]. وقال صلى الله عليه وسلم: (بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ... وَحَجِّ الْبَيْتِ) [متفق عليه]. وما زاد على المرة الواحدة فهو تطوع.","فرضية الحج"));
        list.add(new ItemModel("يجب الحج بخمسة شروط: الإسلام، والعقل، والبلوغ، والحرية، والاستطاعة (وهي القدرة على الزاد والراحلة وأمن الطريق مع فضل عن نفقة من تلزمه نفقتهم). وتشترط للمرأة صحبة زوج أو محرم عند جمهور العلماء. ويصح حج الصبي ويكون له تطوعاً ولا يسقط عنه فرض حجة الإسلام.","شروط وجوب الحج"));
        list.add(new ItemModel("أشهر الحج: شوال وذو القعدة وعشر من ذي الحجة، قال تعالى: (الْحَجُّ أَشْهُرٌ مَّعْلُومَاتٌ) [البقرة: 197]. أما العمرة فتجوز في جميع أيام السنة، وفضلها في رمضان عظيم لقوله صلى الله عليه وسلم: (عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً) [متفق عليه].","أشهر الحج وزمن العمرة"));
        list.add(new ItemModel("العمرة زيارة بيت الله الحرام بنسك مخصوص، وقد اختلف العلماء في حكمها، فهي واجبة عند الشافعية والحنابلة، وسنة مؤكدة عند الحنفية والمالكية. وفضلها عظيم، قال صلى الله عليه وسلم: (الْعُمْرَةُ إِلَى الْعُمْرَةِ كَفَّارَةٌ لِمَا بَيْنَهُمَا، وَالْحَجُّ الْمَبْرُورُ لَيْسَ لَهُ جَزَاءٌ إِلاَّ الْجَنَّةُ) [متفق عليه].","حكم العمرة وفضلها"));
        list.add(new ItemModel("قال صلى الله عليه وسلم: (مَنْ حَجَّ لِلَّهِ فَلَمْ يَرْفُثْ وَلَمْ يَفْسُقْ رَجَعَ كَيَوْمِ وَلَدَتْهُ أُمُّهُ) [متفق عليه]. والحج المبرور هو الخالص لله، الموافق لسنة النبي صلى الله عليه وسلم، المنفَق عليه من مال حلال، البعيد عن المعاصي.","فضل الحج المبرور"));
        list.add(new ItemModel("للحج ثلاثة أنواع: (التمتع) وهو أن يحرم بالعمرة في أشهر الحج ثم يتحلل منها ثم يحرم بالحج في عامه، وهو أفضل الأنواع عند كثير من العلماء. (القِران) وهو أن يحرم بالعمرة والحج معاً أو يدخل الحج على العمرة قبل طوافها، ويبقى محرماً إلى يوم النحر. (الإفراد) وهو أن يحرم بالحج وحده. وعلى المتمتع والقارن هدي، أما المفرد فلا هدي عليه.","أنواع النسك: التمتع والقِران والإفراد"));
        list.add(new ItemModel("الميقات المكاني هو المكان الذي لا يجوز لمن يريد الحج أو العمرة تجاوزه إلا محرماً، وهي: ذو الحليفة (أبيار علي) لأهل المدينة، والجُحفة لأهل الشام ومصر والمغرب (ويحرم من رابغ أو ما يحاذيها)، وقرن المنازل (السيل الكبير) لأهل نجد، ويلملم لأهل اليمن، وذات عرق لأهل العراق. ومن كان داخل المواقيت أحرم من مكانه، وأهل مكة يحرمون بالحج من مكة. والقادم بالطائرة يحرم عند محاذاة الميقات أو قبله.","مواقيت الإحرام"));
        list.add(new ItemModel("يسن قبل الإحرام: الاغتسال، وقص الأظافر والشارب ونتف الإبط وحلق العانة، وتطييب البدن قبل النية، ثم يلبس الرجل إزاراً ورداءً أبيضين نظيفين، وتلبس المرأة ما شاءت من الثياب المباحة دون زينة. ثم ينوي النسك (لبيك عمرة أو لبيك حجاً)، ويصلي إن وافق وقت فريضة.","سنن الإحرام وصفته"));
        list.add(new ItemModel("صيغة التلبية: (لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ) [متفق عليه]. ويرفع الرجل بها صوته، وتخفضه المرأة. ويستمر المعتمر في التلبية حتى يبدأ الطواف، والحاج حتى يرمي جمرة العقبة.","التلبية"));
        list.add(new ItemModel("محظورات الإحرام: حلق الشعر وقص الأظافر، واستعمال الطيب في البدن أو الثياب، وقتل صيد البر أو الإعانة عليه، وعقد النكاح، والجماع ومقدماته. ويختص الرجل بحظر لبس المخيط وتغطية الرأس. وتختص المرأة بحظر النقاب والقفازين. فمن فعل شيئاً منها لزمته الفدية، والجماع قبل التحلل الأول يفسد النسك.","محظورات الإحرام"));
        list.add(new ItemModel("إذا دخل المعتمر الحرم ابتدأ بالطواف، وهو سبعة أشواط من الحجر الأسود إلى الحجر الأسود، تكون الكعبة فيها عن يسار الطائف. ويشترط له الطهارة وستر العورة. ويسن للرجل الاضطباع (كشف الكتف الأيمن) والرمل (الإسراع في المشي) في الأشواط الثلاثة الأولى من طواف القدوم أو العمرة. ويسن استلام الحجر الأسود وتقبيله إن تيسر، وإلا فالإشارة إليه، واستلام الركن اليماني، ويقال بينهما: (رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ).","الطواف بالبيت"));
        list.add(new ItemModel("بعد الطواف يصلي الطائف ركعتين خلف مقام إبراهيم إن تيسر وإلا ففي أي موضع من المسجد، يقرأ فيهما بعد الفاتحة بـ(الكافرون) و(الإخلاص). ثم يشرب من ماء زمزم، قال صلى الله عليه وسلم: (مَاءُ زَمْزَمَ لِمَا شُرِبَ لَهُ) [رواه ابن ماجه]، ويدعو بما شاء.","ركعتا الطواف وشرب زمزم"));
        list.add(new ItemModel("السعي سبعة أشواط بين الصفا والمروة، يبدأ بالصفا وينتهي بالمروة، فالذهاب شوط والعودة شوط آخر. ويسن للرجل الهرولة بين العلمين الأخضرين، وتمشي المرأة. ويشترط أن يكون بعد طواف، والموالاة بين الأشواط، ويسن أن يكون على طهارة. قال تعالى: (إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ) [البقرة: 158].","السعي بين الصفا والمروة"));
        list.add(new ItemModel("بعد السعي يحلق المعتمر رأسه أو يقصر، والحلق أفضل للرجل لدعاء النبي صلى الله عليه وسلم للمحلقين ثلاثاً وللمقصرين مرة، وتقصر المرأة قدر أنملة من أطراف شعرها. وبذلك تنتهي العمرة ويحل لصاحبها كل ما حرم عليه بالإحرام. وأركان العمرة: الإحرام، والطواف، والسعي.","التحلل من العمرة"));
        list.add(new ItemModel("في اليوم الثامن من ذي الحجة (يوم التروية) يحرم المتمتع بالحج من مكان إقامته، ويتجه إلى منى قبل الظهر أو بعده، ويصلي بها الظهر والعصر والمغرب والعشاء والفجر، يقصر الرباعية دون جمع. وهذا المبيت سنة وليس واجباً.","يوم التروية: الثامن من ذي الحجة"));
        list.add(new ItemModel("الوقوف بعرفة ركن الحج الأعظم، قال صلى الله عليه وسلم: (الْحَجُّ عَرَفَةُ) [رواه أبو داود والترمذي]. ويبدأ وقته من زوال شمس التاسع من ذي الحجة، والمجزئ منه أن يوجد في عرفة ولو لحظة قبل فجر يوم النحر. ويسن الجمع بين الظهر والعصر جمع تقديم مع القصر، والإكثار من الدعاء والذكر، وخير الدعاء دعاء يوم عرفة. وحدود عرفة: كلها موقف إلا بطن عرنة، قال صلى الله عليه وسلم: (وَقَفْتُ هَا هُنَا، وَعَرَفَةُ كُلُّهَا مَوْقِفٌ) [رواه مسلم].","الوقوف بعرفة"));
        list.add(new ItemModel("إذا غربت الشمس دفع الحاج إلى مزدلفة بسكينة ووقار، فيصلي بها المغرب والعشاء جمع تأخير مع قصر العشاء، ويبيت بها حتى يصلي الفجر، ثم يقف عند المشعر الحرام يذكر الله ويدعو حتى يسفر الفجر جداً، ثم يدفع إلى منى قبل طلوع الشمس. ويرخص للضعفة والنساء الدفع بعد منتصف الليل. والمبيت بمزدلفة واجب عند الجمهور.","المبيت بمزدلفة"));
        list.add(new ItemModel("أعمال يوم النحر (العاشر من ذي الحجة) على الترتيب: رمي جمرة العقبة بسبع حصيات يكبر مع كل حصاة، ثم ذبح الهدي، ثم الحلق أو التقصير، ثم طواف الإفاضة والسعي للمتمتع. فإذا رمى وحلق حصل التحلل الأول وحل له كل شيء إلا النساء، وإذا طاف الإفاضة حصل التحلل الثاني. ولا حرج في تقديم بعضها على بعض أو تأخيره، فما سئل النبي صلى الله عليه وسلم يومئذ عن شيء قُدِّم ولا أُخِّر إلا قال: (افْعَلْ وَلاَ حَرَجَ) [متفق عليه].","أعمال يوم النحر"));
        list.add(new ItemModel("طواف الإفاضة ركن من أركان الحج لا يصح الحج بدونه، قال تعالى: (وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ) [الحج: 29]. ووقته بعد منتصف ليلة النحر ويستمر إلى آخر أيام الحج، والأفضل أن يؤدى يوم النحر. ويجب فيه ما يجب في الطواف من الطهارة وستر العورة.","طواف الإفاضة"));
        list.add(new ItemModel("أيام التشريق هي الحادي عشر والثاني عشر والثالث عشر من ذي الحجة، يبيت فيها الحاج بمنى، ويرمي الجمرات الثلاث كل يوم بعد الزوال، كل جمرة بسبع حصيات: الصغرى ثم الوسطى ثم الكبرى (جمرة العقبة). ومن تعجل في يومين بعد رمي اليوم الثاني عشر وخرج قبل غروب الشمس فلا إثم عليه، ومن تأخر فرمى اليوم الثالث عشر فهو أفضل. قال تعالى: (فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ) [البقرة: 203].","أيام التشريق ورمي الجمرات"));
        list.add(new ItemModel("طواف الوداع واجب على الحاج الذي يريد مغادرة مكة إلى بلده عند جمهور العلماء، وهو آخر ما يفعله الحاج، قال صلى الله عليه وسلم: (لاَ يَنْفِرَنَّ أَحَدٌ حَتَّى يَكُونَ آخِرُ عَهْدِهِ بِالْبَيْتِ) [رواه مسلم]. ويسقط عن الحائض والنفساء لقول ابن عباس رضي الله عنهما: (أُمِرَ النَّاسُ أَنْ يَكُونَ آخِرُ عَهْدِهِمْ بِالْبَيْتِ إِلاَّ أَنَّهُ خُفِّفَ عَنِ الْحَائِضِ) [متفق عليه].","طواف الوداع"));
        list.add(new ItemModel("أركان الحج عند جمهور العلماء أربعة: الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي. وواجباته: الإحرام من الميقات، والوقوف بعرفة إلى الغروب لمن وقف نهاراً، والمبيت بمزدلفة، ورمي الجمرات، والمبيت بمنى ليالي التشريق، والحلق أو التقصير، وطواف الوداع. فمن ترك ركناً لم يصح حجه حتى يأتي به، ومن ترك واجباً جبره بدم.","أركان الحج وواجباته"));
        list.add(new ItemModel("على المتمتع والقارن هدي شاة أو سُبع بدنة أو سُبع بقرة، قال تعالى: (فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ) [البقرة: 196]. ويذبح يوم النحر وأيام التشريق في الحرم، ويأكل منه ويهدي ويتصدق.","الهدي"));
        list.add(new ItemModel("من ترك واجباً من واجبات الحج أو فعل محظوراً كحلق الشعر لعذر لزمته الفدية. وفدية الأذى (كحلق الرأس أو قص الظفر لعذر) على التخيير: صيام ثلاثة أيام، أو إطعام ستة مساكين، أو ذبح شاة، لقوله تعالى: (فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ) [البقرة: 196]، وفسّره النبي صلى الله عليه وسلم لكعب بن عجرة رضي الله عنه [متفق عليه]. وأما ترك الواجب فعليه دم يذبح في مكة ويوزع على فقراء الحرم.","الفدية ودم الجبران"));
        list.add(new ItemModel("المرأة الحائض أو النفساء تؤدي جميع مناسك الحج والعمرة سوى الطواف بالبيت والصلاة، حتى تطهر، لقوله صلى الله عليه وسلم لعائشة رضي الله عنها: (افْعَلِي مَا يَفْعَلُ الْحَاجُّ غَيْرَ أَنْ لاَ تَطُوفِي بِالْبَيْتِ حَتَّى تَطْهُرِي) [متفق عليه]. فإن لم تتمكن من البقاء حتى تطهر فلها أن تستشير أهل العلم الثقات في حالتها.","الحائض في الحج والعمرة"));
        list.add(new ItemModel("قال تعالى: (فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ) [البقرة: 197]. فمن آداب الحاج: الإخلاص لله، والنفقة من مال حلال، وتعلم أحكام المناسك قبل السفر، وصحبة الصالحين، وحسن الخلق، والصبر على الزحام وكثرة الذكر والدعاء، وقال صلى الله عليه وسلم: (خُذُوا عَنِّي مَنَاسِكَكُمْ) [رواه مسلم].","آداب الحاج والمعتمر"));
        list.add(new ItemModel("زيارة المسجد النبوي ليست من أعمال الحج ولا شرطاً فيه، لكنها مستحبة لمن كان قريباً أو مسافراً إليه، وشد الرحال إليه مشروع لقوله صلى الله عليه وسلم: (لاَ تُشَدُّ الرِّحَالُ إِلاَّ إِلَى ثَلاَثَةِ مَسَاجِدَ: الْمَسْجِدِ الْحَرَامِ، وَمَسْجِدِي هَذَا، وَالْمَسْجِدِ الأَقْصَى) [متفق عليه]. وقال: (صَلاَةٌ فِي مَسْجِدِي هَذَا خَيْرٌ مِنْ أَلْفِ صَلاَةٍ فِيمَا سِوَاهُ إِلاَّ الْمَسْجِدَ الْحَرَامَ) [متفق عليه].","زيارة المسجد النبوي"));

        Adapterrec3 adapterrec3 = new Adapterrec3(list, this);
        binding.rec4.setAdapter(adapterrec3);

        showBanner(binding.adsContainer);
    }
}
